SELECT DISTINCT p.id, p.symbol, p.status, p.close_reason, p.realized_pnl, ROUND(p.quantity*p.entry_price,4) AS notional, f.id AS five_id, f.decision, f.original_decision, a.final_result, p.opened_at FROM crypto_ai.paper_position p JOIN crypto_ai.buy_htf_assessment_audit a ON a.reference_signal_id=p.signal_id JOIN crypto_ai.trade_signal f ON f.id=a.five_minute_signal_id WHERE f.original_decision IN ('SELL','STRONG_SELL') AND f.decision NOT IN ('SELL','STRONG_SELL') ORDER BY p.opened_at LIMIT 50;